	}
	out := make([]state, 0, len(n))
	for _, st := range n {
		if st != forbidden {
			out = append(out, st)
		}
	}
	return out
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
