package twobucket

import "errors"

// state holds the amount of liquid (in liters) in each bucket.
type state struct {
	one int
	two int
}

// Solve determines the minimum number of actions needed to measure exactly
// goalAmount liters using two buckets of the given sizes, starting with
// startBucket ("one" or "two"). It returns the name of the bucket that ends
// up holding the goal amount, the total number of actions, and the amount of
// liquid left in the other bucket.
func Solve(sizeBucketOne, sizeBucketTwo, goalAmount int, startBucket string) (string, int, int, error) {
	if sizeBucketOne <= 0 {
		return "", 0, 0, errors.New("invalid first bucket size")
	}
	if sizeBucketTwo <= 0 {
		return "", 0, 0, errors.New("invalid second bucket size")
	}
	if goalAmount <= 0 {
		return "", 0, 0, errors.New("invalid goal amount")
	}
	if startBucket != "one" && startBucket != "two" {
		return "", 0, 0, errors.New("invalid start bucket name")
	}
	if goalAmount > sizeBucketOne && goalAmount > sizeBucketTwo {
		return "", 0, 0, errors.New("impossible")
	}
	if goalAmount%gcd(sizeBucketOne, sizeBucketTwo) != 0 {
		return "", 0, 0, errors.New("impossible")
	}

	// Breadth-first search over (bucket one, bucket two) states. Because BFS
	// visits states in order of increasing move count, the first state that
	// reaches the goal uses the minimum number of actions.
	steps := map[state]int{{0, 0}: 0}
	queue := []state{{0, 0}}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]

		for _, next := range neighbors(current, sizeBucketOne, sizeBucketTwo, startBucket) {
			if _, seen := steps[next]; seen {
				continue
			}
			if next.one == goalAmount {
				return "one", steps[current]+1, next.two, nil
			}
			if next.two == goalAmount {
				return "two", steps[current]+1, next.one, nil
			}
			steps[next] = steps[current] + 1
			queue = append(queue, next)
		}
	}

	return "", 0, 0, errors.New("impossible")
}

// neighbors returns every state reachable from s in a single action, excluding
// states that violate the rule that the starting bucket may not be empty
// while the other bucket is full.
func neighbors(s state, sizeOne, sizeTwo int, startBucket string) []state {
	pourOneToTwo := min(s.one, sizeTwo-s.two)
	pourTwoToOne := min(s.two, sizeOne-s.one)
	forbidden := state{sizeOne, 0}
	if startBucket == "one" {
		forbidden = state{0, sizeTwo}
	}

	all := []state{
		{sizeOne, s.two},                            // fill bucket one
		{s.one, sizeTwo},                            // fill bucket two
		{0, s.two},                                  // empty bucket one
		{s.one, 0},                                  // empty bucket two
		{s.one - pourOneToTwo, s.two + pourOneToTwo}, // pour one into two
		{s.one + pourTwoToOne, s.two - pourTwoToOne}, // pour two into one
	}

	n := make([]state, 0, len(all))
	for _, st := range all {
		if st != forbidden {
			n = append(n, st)
		}
	}
	return n
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func gcd(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}
